```mermaid
classDiagram
    class CalculatorApp {
        +run()
        -get_input() str
        -display_result(result: float)
        -display_error(error: str)
    }
    class ExpressionParser {
        +parse(expression: str) List[str]
        -tokenize(expression: str) List[str]
        -shunting_yard(tokens: List[str]) List[str]
    }
    class CalculatorEngine {
        +evaluate(tokens: List[str]) float
        -apply_operator(op: str, a: float, b: float) float
    }
    class OutputFormatter {
        +format_result(result: float) str
        +format_error(error: Exception) str
    }
    CalculatorApp --> ExpressionParser
    CalculatorApp --> CalculatorEngine
    CalculatorApp --> OutputFormatter
```

```mermaid
classDiagram
    class Calculator {
        +calculate(expression: str) -> str
    }
    class Tokenizer {
        +tokenize(expression: str) -> List[Token]
    }
    class ShuntingYardParser {
        +parse(tokens: List[Token]) -> List[Token]
    }
    class RpnEvaluator {
        +evaluate(rpn: List[Token]) -> float
    }
    class ResultFormatter {
        +format(value: float) -> str
        +format_error(error: Exception) -> str
    }
    class Token {
        -type: TokenType
        -value: str
        +__init__(type: TokenType, value: str)
        +__repr__() -> str
    }
    class TokenType {
        <<enumeration>>
        NUMBER
        PLUS
        MINUS
        MULTIPLY
        DIVIDE
        LPAREN
        RPAREN
    }
    class CalculatorError {
        <<exception>>
        +message: str
        +__init__(message: str)
    }
    class DivisionByZeroError {
        <<exception>>
        +__init__()
    }
    class InvalidExpressionError {
        <<exception>>
        +__init__(message: str)
    }
    Calculator --> Tokenizer
    Calculator --> ShuntingYardParser
    Calculator --> RpnEvaluator
    Calculator --> ResultFormatter
    Tokenizer --> Token
    ShuntingYardParser --> Token
    RpnEvaluator --> Token
    CalculatorError <|-- DivisionByZeroError
    CalculatorError <|-- InvalidExpressionError
```

```mermaid
classDiagram
    class Calculator {
        +calculate(expression: str) -> str
        -parse(expression: str) -> list
        -evaluate(tokens: list) -> float
        -format_result(value: float) -> str
    }
    class Tokenizer {
        +tokenize(expression: str) -> list
        -is_number(token: str) -> bool
        -is_operator(token: str) -> bool
    }
    class ShuntingYard {
        +to_postfix(tokens: list) -> list
        -precedence(op: str) -> int
    }
    class Evaluator {
        +evaluate_postfix(postfix: list) -> float
        -apply_operator(op: str, a: float, b: float) -> float
    }
    class CalculatorError {
        +message: str
    }
    Calculator --> Tokenizer
    Calculator --> ShuntingYard
    Calculator --> Evaluator
    Calculator --> CalculatorError
```

